/* Phase 3b: starter pack (onboarding portal), probation review workflow (P1/P2/P3), brain games, extra automation */

/* ================= STARTER PACK ================= */
const SP = id => (DB.starterPacks||{})[id];
function newPack(e){ (DB.starterPacks ||= {})[e.id] = {status:'Not started', region:e.region, data:{}, docs:[], signs:{}, office:{}, created:D.todayIso(), submitted:null, note:'', log:[{t:nowStamp(),w:'Starter pack opened'}]}; }
const packTasks = region => region==='UK'
  ? [['newstarter','New starter form'],['medical','Medical questionnaire'],['wtr','Working time regulations – statement and opt-out'],['eo','Equal opportunities form'],['items','Company items and employee handbook'],['rtwdocs','Proof of eligibility to work (UK)'],['p46','P46 / P45 (tax)'],['contract','Contract and job description']]
  : [['newstarter','New starter form'],['medical','Medical questionnaire'],['eo','Equal opportunities form'],['items','Company items and employee handbook'],['iddocs','ID copy and previous employer letter (PK)'],['contract','Contract and job description']];
const TITLES = ['Mr','Mrs','Miss','Ms','Mx','Dr','Other'], MARITAL = ['Single','Married','Civil partnership','Divorced','Widowed','Prefer not to say'];
const SPEC = {
 newstarter:[['h','Your details'],{k:'surname',l:'Surname'},{k:'first',l:'First name(s)'},{k:'title',l:'Title',t:'sel:'+TITLES.join('|')},{k:'dob',l:'Date of birth',t:'date'},{k:'address',l:'Address',t:'area',w:1},{k:'postcode',l:'Postcode / zip code'},{k:'tel',l:'Telephone number',o:1},{k:'mobile',l:'Mobile number'},{k:'email',l:'Email address',t:'email'},{k:'marital',l:'Marital status',t:'sel:'+MARITAL.join('|')},{k:'ni',l:'National Insurance number (UK)',uk:1},{k:'nationality',l:'Nationality'},{k:'idno',l:'Passport / ID card number'},
  ['h','Job details'],{k:'job',l:'Job applied for',ro:1},{k:'startdate',l:'Start date',ro:1},
  ['h','Emergency contacts'],{k:'ec1n',l:'Contact 1 – name'},{k:'ec1t',l:'Contact 1 – telephone'},{k:'ec1r',l:'Contact 1 – relationship'},{k:'ec2n',l:'Contact 2 – name',o:1},{k:'ec2t',l:'Contact 2 – telephone',o:1},{k:'ec2r',l:'Contact 2 – relationship',o:1},
  ['h','Doctor / GP'],{k:'gpn',l:'Dr and/or practice name',o:1},{k:'gpa',l:'Address',o:1},{k:'gpt',l:'Telephone number',o:1},
  ['h','Bank / building society (restricted to HR and Payroll)'],{k:'bank',l:'Bank / building society name'},{k:'bbranch',l:'Branch address'},{k:'bpost',l:'Branch postcode',o:1},{k:'sort',l:'Sort code'},{k:'roll',l:'Roll number (if applicable)',o:1},{k:'accn',l:'Account name'},{k:'accno',l:'Account number'},
  ['h','Previous employment reference (UK) / previous employer letter (PK)'],{k:'prevn',l:'Name / company',o:1},{k:'preva',l:'Address',o:1},{k:'prevd',l:'Start and leave date',o:1}],
 eo:[['h','Monitoring ethnicity'],{k:'eth',l:'How would you describe yourself?',t:'sel:Prefer not to say|Asian or Asian British – Bangladeshi|Asian or Asian British – Indian|Asian or Asian British – Pakistani|Asian or Asian British – any other background|Black or Black British – African|Black or Black British – Caribbean|Black or Black British – any other background|Chinese or another ethnic group – Chinese|Chinese or another ethnic group – any other|Mixed heritage – White and Asian|Mixed heritage – White and Black African|Mixed heritage – White and Black Caribbean|Mixed heritage – any other background|White – British|White – English|White – Irish|White – Scottish|White – Welsh|White – any other background'},{k:'ethother',l:'If “any other”, please write in',o:1},
  ['h','Disability monitoring'],{k:'dis',l:'Do you consider yourself to have a disability or long-term health condition?',t:'sel:Prefer not to say|Yes|No'},{k:'disimpact',l:'What is the effect or impact on you? (optional – helps us make reasonable adjustments)',t:'area',o:1,w:1}],
 wtr:[['h','Working Time Regulations statement (UK)'],{k:'wtr',l:'Other employment',t:'sel:I do not work for an employer other than PFG|I work for other employer(s) – details below'},{k:'wtre',l:'Other employer(s)',o:1},{k:'wtrh',l:'Weekly hours in that employment',o:1},
  ['h','Opt-out agreement (voluntary)'],{k:'optout',l:'Do you agree to work more than an average of 48 hours a week? You do not have to, and you may cancel with 20 working days’ written notice.',t:'sel:No – I do not opt out|Yes – I opt out of the 48-hour limit',w:1}],
 items:[['h','Acceptance of company items'],{k:'fob',l:'I acknowledge receipt of a Key Fob (value £20.00 UK / PKR 4,399 PK) and agree to return it on request or at the end of my employment. I understand I may be charged if it is lost or damaged.',t:'check',w:1},{k:'hb',l:'I have been issued with a copy of the Employee Handbook and briefed on its main parts, and I will familiarise myself with it.',t:'check',w:1}],
 contract:[['h','Contract and job description'],{k:'cread',l:'I have received and read a copy of my contract.',t:'check',w:1},{k:'jread',l:'I have received and read my job description.',t:'check',w:1}]
};
const MED_A = ['Back problems – e.g. sciatica, slipped disc, arthritis or rheumatism?','Upper limb disorders – e.g. tennis elbow, golfer’s elbow, repetitive strain injury (RSI), tenosynovitis?','Any skin complaints – e.g. dermatitis, eczema or other allergic conditions?','Stress, depression, or diagnosed with a stress-related disorder?','Numbness, tingling or discolouration of your fingers – or diagnosed with Vibration White Finger or Raynaud’s?','Any lung complaints – e.g. tuberculosis, pleurisy, asthma or bronchitis?','Any disorder of the heart or circulatory system – e.g. high blood pressure, varicose veins?','Any digestive trouble – e.g. persistent indigestion, ulcers, intestinal complaints, severe diarrhoea in the last six months?','Any psychological or nervous complaints, including paralysis, epilepsy, fits, migraine?','Gout, kidney or bladder complaint?','Diabetes? (If yes, do you require insulin injections?)'];
const MED_B = ['Have you ever failed a medical examination of any kind?','Have you ever consulted (or been recommended to consult) a specialist?','Have you ever been absent from work as a result of a work-related accident?','Have you ever made a claim for Noise Induced Hearing Loss or any other personal injury?','Do you have any ear, nose or throat complaints?','Do you have difficulty hearing a telephone conversation with either ear?','Do you have any eye problems – e.g. recurrent headaches, blurred vision, colour perception problems?','Do you normally wear glasses or contact lenses? If so, which?','Have you ever had your eyes tested? If so, when?','Do you suffer from a medical condition which hinders your sleeping pattern?','Do you require regular medication on a strict timetable?','Have you been absent with sickness from work in the last twelve months? If so, how many days?','Do you have any disability which might require us to provide an adjustment to your workplace?','Do you smoke? If so, how much?','Do you drink alcohol? If so, how many drinks a week?','Are you now, or have you ever been, on treatment for dependency on alcohol and/or drugs?','Do you have any allergies?','Do you take regular exercise? If so, what?','Do you consider yourself to have a disability? Please tell us about any reasonable adjustments we can make.','Have you ever worked in a dusty job?','Have you ever worked in a noisy job?','Have you ever been advised for medical reasons not to do night work, shifts or other kinds of work?','Have you ever had any disease arising out of your work – e.g. deafness, backache, dermatitis, asthma?','Have you previously worked for any other logistics or transport organisation?','Are you currently receiving treatment from a medical professional? Please give details of any recent illness or operations (last 12 months).'];
const DOC_SLOTS = {rtwdocs:[['rtw1','Primary document (e.g. passport, or birth certificate / status document)'],['rtw2','Second document (if required) / share-code evidence']],p46:[['p46','P45, P60 or completed P46 form']],iddocs:[['id','National ID card / passport copy'],['prev','Previous employer letter']]};
const taskBlurb = {newstarter:'Your personal, emergency, GP, bank and previous employer details.',medical:'Confidential health questionnaire (used by HR only, to assess suitability and adjustments).',wtr:'Working time statement and the optional 48-hour opt-out.',eo:'Confidential monitoring information. You may choose “Prefer not to say”.',items:'Acknowledge your key fob and employee handbook.',rtwdocs:'Upload your right-to-work documents. Please also bring your originals on your first day.',p46:'Upload your P45/P60, or complete a P46 if you do not have a P45.',iddocs:'Upload your ID and previous employer letter.',contract:'Confirm you have received your contract and job description.'};
function taskDone(p, key){ const d = p.data[key]; if(DOC_SLOTS[key]) return DOC_SLOTS[key].filter(s=>!(key==='rtwdocs'&&s[0]==='rtw2')).every(s=>p.docs.some(x=>x.slot===s[0])) && (!d || d._done!==false) && !!p.signs[key] ; return !!(d && d._done) && !!p.signs[key]; }
const packProgress = (e, p) => { const t = packTasks(e.region), n = t.filter(([k])=>taskDone(p,k)).length; return {n, total:t.length, pct:Math.round(n/t.length*100)}; };
const starterNeeded = () => { const p = SP(SESSION.uid); return p && p.status!=='Approved'; };
const starterBanner = () => { if(!starterNeeded()) return ''; const p = SP(SESSION.uid), g = packProgress(me(),p); return `<a class="banner" href="#/starter" style="margin-bottom:16px">${ico('clip')}<span><b>Your New Starter Pack is ${p.status==='Submitted'?'with HR for checking':g.pct+'% complete'}.</b> ${p.status==='Submitted'?'':'Please complete the remaining items, upload your documents and sign.'}</span></a>`; };

function fieldHtml(f, vals, ro, region){
  if(typeof f==='string') return `<div class="full"><h4 style="margin:14px 0 8px;padding-bottom:6px;border-bottom:1px solid var(--line)">${esc(f)}</h4></div>`;
  if(f.uk && region!=='UK') return '';
  const v = vals[f.k] ?? '', t = f.t||'text', dis = ro||f.ro ? 'disabled' : '', cls = f.w||t==='area'?'full':'';
  let c;
  if(t==='area') c = `<textarea name="${f.k}" ${dis}>${esc(v)}</textarea>`;
  else if(t==='check') return `<div class="field full"><label class="row" style="gap:10px;align-items:flex-start;font-weight:500"><input type="checkbox" style="width:auto;margin-top:3px" name="${f.k}" ${v?'checked':''} ${dis}> <span>${esc(f.l)}</span></label></div>`;
  else if(t.startsWith('sel:')) c = `<select name="${f.k}" ${dis}><option value="">— choose —</option>${t.slice(4).split('|').map(o=>`<option ${v===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
  else c = `<input type="${t}" name="${f.k}" value="${esc(v)}" ${dis}>`;
  return `<div class="field ${cls}"><label>${esc(f.l)}${f.o?' <span class="muted">(optional)</span>':''}</label>${c}</div>`;
}
const specHtml = (spec, vals, ro, region) => `<div class="fgrid">${spec.map(f=>Array.isArray(f)?fieldHtml(f[1],vals,ro,region):fieldHtml(f,vals,ro,region)).join('')}</div>`;
function collect(form, spec){ const v = {}; spec.forEach(f => { if(Array.isArray(f)) return; const el = form.elements[f.k]; if(!el) return; v[f.k] = (f.t==='check') ? el.checked : el.value.trim(); }); return v; }
function medHtml(vals, ro){ const q = (list, pre) => list.map((t,i)=>{ const k = pre+i, a = vals[k]||{}; return `<tr><td>${esc(t)}</td><td><label><input type="radio" name="${k}" value="Yes" ${a.y==='Yes'?'checked':''} ${ro?'disabled':''} style="width:auto"> Yes</label> <label><input type="radio" name="${k}" value="No" ${a.y==='No'?'checked':''} ${ro?'disabled':''} style="width:auto"> No</label></td><td><input name="${k}d" value="${esc(a.d||'')}" ${ro?'disabled':''} placeholder="If yes, give details"></td></tr>`; }).join('');
  return `<div class="fgrid"><div class="field"><label>Gender (optional)</label><input name="gender" value="${esc(vals.gender||'')}" ${ro?'disabled':''}></div><div class="field"><label>Height / weight (optional)</label><input name="hw" value="${esc(vals.hw||'')}" ${ro?'disabled':''}></div></div>
  <h4 style="margin:12px 0 6px">Section A – have you experienced one or more of the following?</h4><div class="tw"><table class="t"><thead><tr><th>Condition</th><th>Answer</th><th>Details</th></tr></thead><tbody>${q(MED_A,'a')}</tbody></table></div>
  <h4 style="margin:16px 0 6px">Section B</h4><div class="tw"><table class="t"><thead><tr><th>Question</th><th>Answer</th><th>Details</th></tr></thead><tbody>${q(MED_B,'b')}</tbody></table></div>
  <p class="small muted" style="margin-top:10px">Declaration: I understand this information is used to assess my suitability for employment. I have answered honestly and have not knowingly withheld important information about my physical or mental health. I understand wilful concealment of a material fact may make me liable to dismissal.</p>`; }
function collectMed(form){ const v = {gender:form.elements.gender.value.trim(), hw:form.elements.hw.value.trim()}; let miss = 0; [[MED_A,'a'],[MED_B,'b']].forEach(([l,p])=>l.forEach((_,i)=>{ const k = p+i, r = form.querySelector(`input[name=${k}]:checked`), d = form.elements[k+'d'].value.trim(); v[k] = {y:r?r.value:'',d}; if(!r || (r.value==='Yes' && !d)) miss++; })); return {v, miss}; }
function sigHtml(key, p, ro){ const s = p.signs[key]; return `<div class="card flat" style="margin-top:14px"><b>Electronic signature</b>${s?`<div class="row" style="margin-top:8px"><div><div style="font:italic 22px Georgia,serif">${esc(s.name)}</div><div class="small muted">Signed ${fmtDT(s.t)}</div></div>${s.img?`<img src="${s.img}" alt="Drawn signature" style="height:50px;border-bottom:1px solid var(--line)">`:''}</div>`
  : `<p class="small muted" style="margin:6px 0">Type your full name and tick the box. You may also draw your signature (optional).</p><div class="fgrid"><div class="field"><label>Full name</label><input name="signname" placeholder="${esc(me().name)}"></div><div class="field"><label>Draw signature (optional)</label><canvas class="sigc" width="320" height="80" style="border:1px dashed #9db3bb;border-radius:8px;width:100%;background:#fff;touch-action:none"></canvas><button type="button" class="btn sm" data-act="sigClear">Clear</button></div></div><label class="row" style="gap:8px;font-weight:500"><input type="checkbox" name="signok" style="width:auto"> I agree that typing my name is my electronic signature and has the same effect as a handwritten signature.</label>`}</div>`; }
let sigDown = false;
document.addEventListener('pointerdown', e => { const c = e.target.closest('canvas.sigc'); if(!c) return; sigDown = true; const r = c.getBoundingClientRect(), x = c.getContext('2d'); x.lineWidth = 2; x.lineCap = 'round'; x.beginPath(); x.moveTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height); c.dataset.drawn = 1; e.preventDefault(); });
document.addEventListener('pointermove', e => { if(!sigDown) return; const c = e.target.closest('canvas.sigc'); if(!c) return; const r = c.getBoundingClientRect(), x = c.getContext('2d'); x.lineTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height); x.stroke(); });
document.addEventListener('pointerup', () => { sigDown = false; });
ACT.sigClear = el => { const c = el.parentElement.querySelector('canvas'); c.getContext('2d').clearRect(0,0,c.width,c.height); delete c.dataset.drawn; };
function readSig(form, p, key){ if(p.signs[key]) return true; const n = form.elements.signname?.value.trim(), ok = form.elements.signok?.checked; if(!n || n.length<3 || !ok){ toast('Please type your full name and tick the signature box.','bad'); return false; } if(n.toLowerCase()!==me().name.toLowerCase() && !confirm('The name typed does not match your portal name. Sign anyway?')) return false; const c = form.querySelector('canvas.sigc'); p.signs[key] = {name:n,t:nowStamp(),img:c && c.dataset.drawn ? c.toDataURL('image/png') : null}; return true; }

VIEWS.starter = () => { const e = me(), p = SP(e.id); if(!p) return `<div class="banner">No starter pack is open for you.</div>`; const tasks = packTasks(e.region), g = packProgress(e,p), locked = p.status==='Submitted' || p.status==='Approved';
  return pageHead('My New Starter Pack','Welcome to Pentagon Food Group. Please complete each item, upload your documents and sign. Your answers are only seen by HR and Payroll.') +
  `<div class="card" style="margin-bottom:16px"><div class="row sp wrap"><div><b>${g.n} of ${g.total} items complete</b><div class="small muted">${e.region==='UK'?'UK new starter pack':'PK new starter pack (assumption: UK-only items removed)'} · Status: ${statusBadge(p.status==='Not started'?'Pending':p.status)}</div></div>${locked?badge(p.status==='Approved'?'Approved by HR':'Submitted – with HR','ok'):`<button class="btn pri" data-act="spSubmit" ${g.n===g.total?'':'disabled'}>${ico('check')} Submit to HR</button>`}</div><div class="prog ${g.pct===100?'g':''}" style="margin-top:12px"><i style="width:${g.pct}%"></i></div>${p.note?`<div class="banner" style="margin:12px 0 0">${ico('warn')}<span><b>HR feedback:</b> ${esc(p.note)}</span></div>`:''}</div>
  <div class="grid g2">${tasks.map(([k,l])=>{ const done = taskDone(p,k), started = p.data[k] || p.docs.some(x=>DOC_SLOTS[k]&&DOC_SLOTS[k].some(s=>s[0]===x.slot)); return `<div class="card"><div class="row sp"><b>${esc(l)}</b>${done?badge('Complete','ok'):started?badge('In progress','warn'):badge('To do')}</div><p class="small muted" style="margin:6px 0 12px">${esc(taskBlurb[k])}</p><button class="btn sm ${done?'':'pri'}" data-act="spOpen" data-k="${k}">${locked?'View':done?'Review':'Open'}</button></div>`; }).join('')}</div>
  <p class="small muted" style="margin-top:14px">Questions? Email hr@pentagonfoodgroup.co.uk. Your information is processed in line with data-protection law; special-category data (health, equality) is visible to HR only.</p>`; };
ACT.spOpen = el => { const e = me(), p = SP(e.id), k = el.dataset.k, label = packTasks(e.region).find(t=>t[0]===k)[1], ro = p.status==='Submitted'||p.status==='Approved', d = p.data[k]||{};
  let body;
  if(DOC_SLOTS[k]) body = `<p class="muted small">${esc(taskBlurb[k])} Files up to 300 KB (PDF, JPG or PNG) in this prototype.</p>${k==='rtwdocs'?`<div class="field"><label>Share code (if you have one)</label><input id="spsc" value="${esc(d.sharecode||'')}" ${ro?'disabled':''}></div>`:''}${DOC_SLOTS[k].map(([sl,lb])=>{ const doc = p.docs.find(x=>x.slot===sl); return `<div class="card flat" style="margin-bottom:10px"><b class="small">${esc(lb)}</b>${doc?`<div class="row sp" style="margin-top:6px"><span class="small">${esc(doc.name)} · ${Math.round(doc.size/1024)} KB</span>${ro?'':`<button class="btn sm" data-act="spDocDel" data-slot="${sl}" data-k="${k}">Remove</button>`}</div>`:ro?'<div class="muted small">Not uploaded</div>':`<input type="file" accept=".pdf,.jpg,.jpeg,.png" data-chg="spDoc" data-slot="${sl}" data-k="${k}" style="margin-top:6px">`}</div>`; }).join('')}<form id="spf" onsubmit="return false">${sigHtml(k,p,ro)}</form>`;
  else body = `<form id="spf" onsubmit="return false">${k==='medical'?medHtml(d,ro):specHtml(SPEC[k].map(f=>f), k==='newstarter'?{job:e.title,startdate:fmt(e.start),email:e.email,first:e.name.split(' ')[0],surname:e.name.split(' ').slice(1).join(' '),...d}:d, ro, e.region)}${sigHtml(k,p,ro)}<div id="spe" class="err"></div></form>`;
  modal({title:esc(label),size:'wide',body,actions:ro?[{label:'Close',act:'closeModal'}]:[{label:'Cancel',act:'closeModal'},{label:'Save & mark complete',cls:'pri',act:'spSave',data:`data-k="${k}"`}]});
  $$('canvas.sigc').forEach(c=>{ c.getContext('2d').strokeStyle = '#06566a'; }); };
CHG.spDoc = el => { const f = el.files[0]; if(!f) return; if(f.size>300*1024){ toast('File is larger than 300 KB.','bad'); el.value=''; return; } const rd = new FileReader(); rd.onload = () => { const p = SP(SESSION.uid); p.docs = p.docs.filter(x=>x.slot!==el.dataset.slot); p.docs.push({slot:el.dataset.slot,name:f.name,size:f.size,data:rd.result,t:nowStamp()}); log('Starter doc uploaded',f.name); saveDB(); ACT.spOpen({dataset:{k:el.dataset.k}}); }; rd.readAsDataURL(f); };
ACT.spDocDel = el => { const p = SP(SESSION.uid); p.docs = p.docs.filter(x=>x.slot!==el.dataset.slot); saveDB(); ACT.spOpen({dataset:{k:el.dataset.k}}); };
ACT.spSave = el => submitOnce(el, () => { const e = me(), p = SP(e.id), k = el.dataset.k, f = $('#spf'), er = $('#spe'); const fail = m => { if(er){ er.textContent = m; er.classList.add('show'); } else toast(m,'bad'); };
  if(DOC_SLOTS[k]){ const need = DOC_SLOTS[k].filter(s=>!(k==='rtwdocs'&&s[0]==='rtw2')); if(!need.every(s=>p.docs.some(x=>x.slot===s[0]))) return toast('Please upload the required document(s).','bad'); p.data[k] = {_done:true, sharecode:$('#spsc')?.value.trim()||''}; }
  else if(k==='medical'){ const {v,miss} = collectMed(f); if(miss) return fail(`Please answer every question (${miss} still need an answer or details).`); p.data[k] = {...v,_done:true}; }
  else { const spec = SPEC[k], v = collect(f, spec), bad = spec.filter(x=>!Array.isArray(x) && !x.o && !x.ro && !(x.uk&&e.region!=='UK') && (x.t==='check' ? !v[x.k] : !v[x.k])); if(bad.length) return fail('Please complete: '+bad.map(x=>x.l.length>40?x.l.slice(0,40)+'…':x.l).join('; ')); if(k==='newstarter' && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.email)) return fail('Enter a valid email address.'); if(k==='newstarter' && v.dob && !validDate(v.dob)) return fail('Enter a valid date of birth.'); p.data[k] = {...v,_done:true}; }
  if(!readSig(f||document.createElement('form'), p, k)){ if(DOC_SLOTS[k]) return; delete p.data[k]._done; return; }
  if(p.status==='Not started') p.status = 'In progress'; p.log.push({t:nowStamp(),w:'Completed: '+packTasks(e.region).find(t=>t[0]===k)[1]}); log('Starter pack item completed',k); saveDB(); closeModal(); toast('Saved','ok'); render(); });
ACT.spSubmit = () => { const e = me(), p = SP(e.id); if(packProgress(e,p).n<packProgress(e,p).total) return; p.status = 'Submitted'; p.submitted = nowStamp(); p.note = ''; p.log.push({t:nowStamp(),w:'Submitted to HR'}); notify(DB.emps.filter(x=>x.role==='hr'||x.role==='admin').map(x=>x.id), `${e.name} submitted their New Starter Pack for checking.`, 'onboarding'); log('Starter pack submitted',''); saveDB(); toast('Submitted to HR – thank you!','ok'); render(); };

/* ---- HR side ---- */
function spAdmin(noTabs){ const none = DB.emps.filter(e=>e.status==='active' && !SP(e.id) && e.role!=='admin'); const rows = Object.entries(DB.starterPacks||{}).filter(([id])=>emp(id)).map(([id,p])=>({e:emp(id),p,g:packProgress(emp(id),p)}));
  return pageHead(noTabs?'Starter Packs':'Onboarding & Exit','Each new employee completes their starter pack online: forms, uploads and signatures. HR checks and approves it here.') + (noTabs?'':tabsHtml('onb',[['on','Onboarding'],['sp','Starter packs'],['ex','Exit & clearance']],'on')) +
  table([{h:'Employee',f:r=>`<div class="row">${av(r.e,30)}<div><b>${esc(r.e.name)}</b><div class="small muted">${esc(r.e.title)} · ${r.e.region} · starts ${fmt(r.e.start)}</div></div></div>`},{h:'Progress',f:r=>`<div class="prog ${r.g.pct===100?'g':''}" style="min-width:120px"><i style="width:${r.g.pct}%"></i></div><div class="small muted">${r.g.n}/${r.g.total} items</div>`},{h:'Status',f:r=>statusBadge(r.p.status==='Not started'?'Pending':r.p.status)},{h:'Sign-in',f:r=>r.e.mustChange?badge('Not yet signed in','warn'):badge('Active','ok')},{h:'',cls:'right nowrap',f:r=>`<button class="btn sm pri" data-act="spReview" data-id="${r.e.id}">Review</button> <button class="btn sm" data-act="resendCred" data-id="${r.e.id}" title="Email a new temporary password">${ico('mail')}</button>`}], rows, {empty:'No starter packs yet. They are created automatically when an employee is added.'}) + `<h3 style="margin:22px 0 8px">Employees without a starter pack</h3><p class="small muted">Create a pack for an existing employee if they still need to complete one.</p>` + table([{h:'Employee',f:e=>`${esc(e.name)} <span class="small muted">${esc(e.title)} · ${e.region}</span>`},{h:'',cls:'right',f:e=>`<button class="btn sm" data-act="spCreate" data-id="${e.id}">Create starter pack</button>`}], none, {empty:'Everyone has a starter pack.'}); }
VIEWS.starterpacks = () => spAdmin(true);
ACT.spCreate = el => { const e = emp(el.dataset.id); newPack(e); notify(e.id,'Please complete your New Starter Pack.','starter'); log('Starter pack created','',e.id); saveDB(); toast('Starter pack created for '+e.name+' – they will see “My Starter Pack” when they sign in','ok'); render(); };
ACT.spReview = el => { const e = emp(el.dataset.id), p = SP(e.id), o = p.office||{}; const rd = (k) => `<dt>${k}</dt>`;
  const sec = ([k,l]) => { const d = p.data[k]||{}; let inner; if(DOC_SLOTS[k]) inner = DOC_SLOTS[k].map(([sl,lb])=>{ const x = p.docs.find(y=>y.slot===sl); return `<div class="small">${esc(lb)}: ${x?`<a href="#" data-act="spDl" data-id="${e.id}" data-slot="${sl}">${esc(x.name)}</a>`:'<span class="muted">not uploaded</span>'}</div>`; }).join('')+(d.sharecode?`<div class="small">Share code: ${esc(d.sharecode)}</div>`:'');
    else if(k==='medical') inner = [[MED_A,'a'],[MED_B,'b']].map(([ls,pr])=>ls.map((t,i)=>d[pr+i]&&d[pr+i].y==='Yes'?`<div class="small"><b>Yes</b> – ${esc(t)} <i>${esc(d[pr+i].d)}</i></div>`:'').join('')).join('')||'<div class="small muted">All answers “No”.</div>';
    else inner = `<dl class="dl">${SPEC[k].filter(f=>!Array.isArray(f)).map(f=>`<dt>${esc(f.l.length>46?f.l.slice(0,46)+'…':f.l)}</dt><dd>${f.t==='check'?(d[f.k]?'Yes':'No'):esc(d[f.k]||'—')}</dd>`).join('')}</dl>`;
    const s = p.signs[k]; return `<div class="card flat" style="margin-bottom:10px"><div class="row sp"><b>${esc(l)}</b>${taskDone(p,k)?badge('Complete','ok'):badge('Incomplete','warn')}</div><div style="margin-top:8px">${inner}</div>${s?`<div class="small muted" style="margin-top:6px">Signed by ${esc(s.name)} · ${fmtDT(s.t)}</div>`:''}</div>`; };
  const of = (k,l,t='text') => `<div class="field"><label>${l}</label><input type="${t}" name="${k}" value="${esc(o[k]||'')}"></div>`;
  modal({title:'Starter pack – '+esc(e.name),size:'xl',body:`<div class="banner info">${ico('lock')}<span>Contains special-category and financial data. Access is logged.</span></div>${packTasks(e.region).map(sec).join('')}
  <h4 style="margin:16px 0 8px">Office use only</h4><form id="of"><div class="fgrid">${of('lma','Line manager authorisation – name')}${of('lmd','Line manager authorisation – date','date')}${of('dira','Director authorisation – name')}${of('dird','Director authorisation – date','date')}${of('tsby','Entered on TeamSeer by')}${of('accd','Passed to accounts – date','date')}${of('sal','Annual wage / salary (£ / PKR)')}${of('hrs','Actual hours to be worked')}${of('days','Days to be worked')}${of('car','Company car category')}${of('lic','Driving licence checked')}${of('eno','Employee number')}<div class="field"><label>Employee status</label><select name="st"><option ${o.st==='Permanent'?'selected':''}>Permanent</option><option ${o.st==='Temporary'?'selected':''}>Temporary</option></select></div>${of('payby','Received in Payroll by')}${of('payd','Date received','date')}</div></form>
  <div class="field"><label>Message to the employee (if returning for corrections)</label><textarea id="spn">${esc(p.note||'')}</textarea></div>`,
  actions:[{label:'Close',act:'closeModal'},{label:'Save office use',act:'spOffice',data:`data-id="${e.id}"`},{label:'Return for changes',act:'spReturn',data:`data-id="${e.id}"`},{label:'Approve pack',cls:'ok',act:'spApprove',data:`data-id="${e.id}"`}]}); };
ACT.spDl = (el,ev) => { const d = SP(el.dataset.id).docs.find(x=>x.slot===el.dataset.slot); const a = document.createElement('a'); a.href = d.data; a.download = d.name; document.body.appendChild(a); a.click(); a.remove(); log('Starter doc downloaded',d.name,el.dataset.id); };
ACT.spOffice = el => { const p = SP(el.dataset.id), f = $('#of'); p.office = Object.fromEntries([...new FormData(f)]); log('Starter pack office use updated','',el.dataset.id); saveDB(); toast('Saved','ok'); };
ACT.spReturn = el => { const p = SP(el.dataset.id), n = $('#spn').value.trim(); if(n.length<5) return toast('Add a message explaining what to correct.','bad'); p.status = 'In progress'; p.note = n; p.log.push({t:nowStamp(),w:'Returned for changes by '+me().name}); notify(el.dataset.id, 'HR has asked for changes to your New Starter Pack.', 'starter'); log('Starter pack returned','',el.dataset.id); saveDB(); closeModal(); render(); };
ACT.spApprove = el => { const p = SP(el.dataset.id), e = emp(el.dataset.id); if(packProgress(e,p).n<packProgress(e,p).total) return toast('The pack is not complete yet.','bad'); p.status = 'Approved'; p.note = ''; p.office = Object.fromEntries([...new FormData($('#of'))]); p.log.push({t:nowStamp(),w:'Approved by '+me().name});
  e.phone = p.data.newstarter?.mobile || e.phone; if(p.data.newstarter) e.emergency = {name:p.data.newstarter.ec1n,rel:p.data.newstarter.ec1r,phone:p.data.newstarter.ec1t}; e.history.unshift({t:nowStamp(),by:me().name,what:'Starter pack approved'});
  const ob = DB.onboarding.find(o=>o.emp===e.id); if(ob) ob.tasks.forEach(t=>{ if(/Right-to-Work|Policies/.test(t.t)) t.d = 1; }); notify(e.id,'Your New Starter Pack was approved. Thank you!','dashboard'); log('Starter pack approved','',e.id); saveDB(); closeModal(); toast('Pack approved','ok'); render(); };

/* ================= PROBATION REVIEW WORKFLOW (P1 / P2 / P3) ================= */
const R3 = ['Improvement required','Satisfactory','Good'], R5 = ['Below Average','Average','Satisfactory','Good','Excellent'], H3 = ['Excellent','Satisfactory','Needs Improvement'], REC = ['Approved','Extended','Not Approved'], YN = ['Yes','No'];
const P3E = [['qty','Quantity – meets deadlines'],['know','Knowledge – able to perform within job specifications'],['team','Teamwork – able to work with others'],['comm','Communication skills – presents ideas and information to others'],['qual','Quality – delivers as per requirement'],['meth','Methodically – knows how to do all work within set objectives'],['effv','Effectively – work is valuable'],['prec','Precisely – work is presentable'],['judg','Judgement – makes decisions based on sound reasoning'],['dep','Job dependability – reliable in carrying out instructions'],['att','Attitude – accepts challenges and follows instructions'],['relm','Relation with manager – responds to the manager’s directions'],['env','Adapting to company environment – fits the culture of the company']];
const PSPEC = {
 30:{title:'30 – Days Probationary Period Review Form',
  m:[{k:'att',l:'Attendance, Holidays & Timekeeping',t:'area'},{k:'conduct',l:'Conduct & Attitude',t:'area'},{k:'quality',l:'Quality of work & Productivity',t:'area'},{k:'disc',l:'Disciplinary Action Taken',t:'area',o:1},{k:'lm',l:'Line Manager additional comments',t:'area',o:1}],
  h:[{k:'hc',l:'HR Comments',t:'area',o:1}], e:[{k:'ec',l:'Employee Comments',t:'area',o:1}]},
 60:{title:'60 – Days Probationary Period Review Form',
  m:[{k:'quality',l:'Quality and accuracy of work',t:'r3'},{k:'eff',l:'Efficiency and productivity',t:'r3'},{k:'rel',l:'Work relationships (teamwork and interpersonal communication skills)',t:'r3'},{k:'comp',l:'Competency in the role',t:'r3'},{k:'obj',l:'Have the objectives identified for this period of the probation been met?',t:'yn'},{k:'train',l:'Have the training / development needs identified for this period been addressed?',t:'yn'},{k:'done',l:'Has the employee successfully completed the probationary period (60 Days)?',t:'yn'},{k:'disc',l:'Disciplinary action taken?',t:'yn'},{k:'lm',l:'Line Manager Comments (new targets or additional remarks)',t:'area',o:1}],
  h:[{k:'att',l:'Attendance (Holidays) – filled by AM / HR',t:'r3'},{k:'tk',l:'Time Keeping & Breaks – filled by AM / HR',t:'r3'},{k:'hc',l:'HR Comments',t:'area',o:1}],
  e:[{k:'culture',l:'Are you feeling comfortable in the Company’s culture?',t:'yn'},{k:'training',l:'Are you receiving training related to your job description daily?',t:'yn'},{k:'prog',l:'Has your manager discussed your progress to date?',t:'yn'},{k:'rem',l:'Additional remarks',t:'area',o:1}]},
 90:{title:'Performance Evaluation for Probation Period (90 Days)',
  m:[{k:'objs',l:'List of objectives assigned to the probationer',t:'area'},{k:'ach',l:'Achievements related to the assigned objectives (supporting details must be attached)',t:'area'},{k:'overall',l:'Overall performance rating',t:'r5'},...P3E.map(([k,l])=>({k:'p_'+k,l,t:'r5'})),{k:'couns',l:'Was counselling to the employee required?',t:'yn'},{k:'conf',l:'Has the employee successfully completed the probationary period and should be confirmed?',t:'yn'},{k:'ext',l:'Should the probationary period be extended?',t:'yn'},{k:'extwhy',l:'If extended: reason, concerns, and how they will be addressed during the extension',t:'area',o:1},{k:'other',l:'Other positions or areas this person should be considered for; unusual skills or abilities',t:'area',o:1},{k:'obs',l:'Any other observations?',t:'area',o:1},{k:'rec',l:'Recommendation of the Supervisor / Head of Department',t:'rec'}],
  h:[{k:'att',l:'Attendance / punctuality',t:'h3'},{k:'attc',l:'Comments',o:1},{k:'abs',l:'Absenteeism',t:'h3'},{k:'absc',l:'Comments',o:1},{k:'brk',l:'Break management',t:'h3'},{k:'brkc',l:'Comments',o:1},{k:'final',l:'HR’s final remarks',t:'area'},{k:'rec',l:'Recommendation by HR',t:'rec'}],
  e:[{k:'rem',l:'Employee remarks',t:'area',o:1}]}
};
const SEC_NAME = {m:'Line manager section',h:'HR section',e:'Employee section'};
const pvOf = id => (DB.probReviews||[]).find(r=>r.id===id);
const pvAccess = rv => { const e = emp(rv.emp), u = me(); return {m: managersOf(e).includes(u.id) || isAdmin(), h: isHR(), e: e.id===u.id, any: isHR() || managersOf(e).includes(u.id) || e.id===u.id}; };
const pvTurn = rv => ({'Awaiting manager':'m','Awaiting HR':'h','Awaiting employee':'e'})[rv.status];
const pvLabel = rv => `${rv.stage}-day${rv.round?` (extension ${rv.round})`:''}`;
function pvEmailBody(rv, to, what){ const e = emp(rv.emp); return `Hi ${first(empName(to))},\n\n${what}\n\nEmployee: ${e.name} (${e.title})\nReview: ${pvLabel(rv)} probation review (due ${fmt(rv.due)})\n\nPlease sign in to the HR portal and open Probation ▸ ${e.name}. The form follows our standard probation template.\n\nGlobal HR Team`; }
function pvMail(rv, to, subject, what){ return sendMail(to, subject, pvEmailBody(rv,to,what), 'Probation review', {pv:rv.id}); }
function attSnap(e, from, to){ let hol=0, sickD=0, sp=0, un=0, late=0; DB.leave.filter(l=>l.emp===e.id && l.status==='approved' && l.end>=from && l.start<=to).forEach(l=>{ const d = recDays({...l,start:l.start<from?from:l.start,end:l.end>to?to:l.end},e.region); if(l.type==='HOL') hol+=d; else if(LT[l.type].sick){ sickD+=d; sp++; } else if(l.type==='UNAUTH') un+=d; else if(l.type==='LATE') late++; });
  const an = (DB.anoms||[]).filter(a=>a.emp===e.id && a.date>=from && a.date<=to); return {hol,sickD,sp,un,late,an:an.length,anTypes:[...new Set(an.map(a=>a.type))].join(', ')}; }

VIEWS.probation = (param) => param && pvOf(param) ? pvForm(pvOf(param)) : pvList();
function pvList(){
  const mine = (DB.probReviews||[]).filter(r=>{ const a = pvAccess(r), t = pvTurn(r); return t && a[t] && emp(r.emp)?.status==='active'; });
  const people = DB.emps.filter(e=>e.probation && !e.probation.done && e.status==='active' && (isHR() || e.id===SESSION.uid || manageable().some(m=>m.id===e.id)));
  const done = DB.emps.filter(e=>e.probation && e.probation.done && e.probation.confirmed>=D.iso(D.add(D.today(),-90)) && (isHR()||manageable().some(m=>m.id===e.id))).slice(0,6);
  const chip = r => { const t = {Complete:['Complete','ok'],Scheduled:['Scheduled',''],'Awaiting manager':['With manager','warn'],'Awaiting HR':['With HR','warn'],'Awaiting employee':['With employee','warn'],'Awaiting decision':['Decision needed','bad']}[r.status]; const od = r.status!=='Complete' && r.due<D.todayIso(); return badge(t[0]+(od&&r.status!=='Scheduled'?' · overdue':''), od&&r.status!=='Scheduled'?'bad':t[1]); };
  const card = e => { const rs = DB.probReviews.filter(r=>r.emp===e.id).sort((a,b)=>a.due.localeCompare(b.due)), ly = curLY(e), b = balance(e,ly);
    return `<div class="card"><div class="row">${av(e,42)}<div class="grow"><b>${esc(e.name)}</b><div class="small muted">${esc(e.title)} · ${e.region} · started ${fmt(e.start)} · probation ends ${fmt(e.probation.end)}</div></div>${e.probation.done?badge('Confirmed '+fmtS(e.probation.confirmed),'ok'):badge('In probation','warn')}</div>
    ${e.region==='PK'?`<div class="banner info" style="margin:10px 0 0;padding:8px 12px">${ico('help')}<span class="small">PK leave: ${e.probation.done?`confirmed – ${num1(b.ent)} holidays and ${num1(b.sickEnt)} sick days for ${lyLabel(e,ly)}.`:`${num1(b.ent)} holidays now; the rest (pro-rata of ${DB.settings.quota.PK} holidays) and ${(DB.settings.sickQuota||{}).PK} sick days are added when probation is confirmed.`}</span></div>`:''}
    <div style="margin-top:12px">${rs.map(r=>`<div class="li"><b style="width:112px">${pvLabel(r)}</b><span class="small muted" style="width:78px">${fmtS(r.due)}</span><span class="grow">${chip(r)}${r.legacy?` <span class="small muted">${esc(r.legacy)}</span>`:''}</span>${r.status==='Scheduled'&&isHR()?`<button class="btn sm" data-act="pvStart" data-id="${r.id}">Start now</button>`:''}<button class="btn sm ${pvTurn(r)&&pvAccess(r)[pvTurn(r)]?'pri':''}" data-act="go" data-to="probation/${r.id}">${pvTurn(r)&&pvAccess(r)[pvTurn(r)]?'Complete form':'Open'}</button></div>`).join('')}</div></div>`; };
  return pageHead('Probation 30 / 60 / 90','Reviews are scheduled automatically. The manager is emailed a week before each review is due; then HR and the employee complete their sections.') +
  (mine.length?`<div class="card" style="margin-bottom:16px;border-color:var(--navy2)"><h3>Waiting for you ${badge(String(mine.length),'bad')}</h3>${mine.map(r=>`<div class="li">${av(r.emp,30)}<div class="grow"><b>${esc(empName(r.emp))}</b> – ${pvLabel(r)} review<div class="small muted">${SEC_NAME[pvTurn(r)]} · due ${fmt(r.due)}</div></div><button class="btn sm pri" data-act="go" data-to="probation/${r.id}">Open form</button></div>`).join('')}</div>`:'') +
  `<div class="grid g2">${people.map(card).join('')||'<div class="card empty">No employees currently in probation.</div>'}</div>` + (done.length?`<h3 style="margin:22px 0 10px">Recently confirmed</h3><div class="grid g2">${done.map(card).join('')}</div>`:''); }
ACT.pvStart = el => { const r = pvOf(el.dataset.id); r.status = 'Awaiting manager'; r.log.push({t:nowStamp(),w:'Review started by '+me().name}); const e = emp(r.emp); managersOf(e).forEach(m=>pvMail(r,m,`Probation ${pvLabel(r)} review: ${e.name}`,`The ${pvLabel(r)} probation review for ${e.name} is ready for your section.`)); saveDB(); toast('Manager notified by email (simulated)','ok'); render(); };

function pvForm(rv){
  const e = emp(rv.emp), a = pvAccess(rv), S = PSPEC[rv.stage], turn = pvTurn(rv), st = rv.status;
  if(!a.any) return `<div class="banner">${ico('lock')} You do not have access to this review.</div>`;
  if(rv.legacy && !rv.m.m_done && st==='Complete' && !Object.keys(rv.m).length) return `<p><a href="#/probation">← Probation</a></p><div class="card"><h3>${S.title}</h3><p>${esc(e.name)} – legacy record: <b>${esc(rv.legacy)}</b></p></div>`;
  const prior = DB.probReviews.filter(r=>r.emp===rv.emp && r.id!==rv.id);
  const showSec = s => a.h || a.m || s==='e' || ['Awaiting employee','Awaiting decision','Complete'].includes(st);
  const canEdit = s => turn===s && a[s];
  const snap = attSnap(e, e.start, rv.due>D.todayIso()?D.todayIso():rv.due);
  const ctl = (f, val, ro) => { const dis = ro?'disabled':''; const opt = L => `<option value="">— choose —</option>${L.map(o=>`<option ${val===o?'selected':''}>${esc(o)}</option>`).join('')}`;
    const c = f.t==='area' ? `<textarea name="${f.k}" ${dis}>${esc(val||'')}</textarea>` : f.t==='yn' ? `<select name="${f.k}" ${dis}>${opt(YN)}</select>` : f.t==='r3' ? `<select name="${f.k}" ${dis}>${opt(R3)}</select>` : f.t==='r5' ? `<select name="${f.k}" ${dis}>${opt(R5)}</select>` : f.t==='h3' ? `<select name="${f.k}" ${dis}>${opt(H3)}</select>` : f.t==='rec' ? `<select name="${f.k}" ${dis}>${opt(REC)}</select>` : `<input name="${f.k}" value="${esc(val||'')}" ${dis}>`;
    return `<div class="field ${f.t==='area'?'full':''}"><label>${esc(f.l)}${f.o?' <span class="muted">(optional)</span>':''}</label>${c}</div>`; };
  const part = s => { const vals = rv[s]||{}, ro = !canEdit(s), sg = rv.sigs[s];
    if(!showSec(s)) return `<div class="card flat" style="margin-bottom:14px"><h3>${SEC_NAME[s]}</h3><div class="muted small">This section becomes visible to you once the manager and HR sections are complete.</div></div>`;
    return `<div class="card" style="margin-bottom:14px;${canEdit(s)?'border-color:var(--navy2);box-shadow:0 0 0 3px rgba(6,138,162,.15)':''}"><h3><span class="l">${SEC_NAME[s]}</span>${sg?badge('Submitted '+fmtDT(sg.t),'ok'):canEdit(s)?badge('Your turn','warn'):badge('Not yet','')}</h3><form id="pv-${s}" onsubmit="return false"><div class="fgrid">${S[s].map(f=>ctl(f, vals[f.k], ro)).join('')}</div></form>${sg?`<div class="small muted">Signed electronically by ${esc(sg.name)} on ${fmtDT(sg.t)}</div>`:''}${canEdit(s)?`<div class="row" style="margin-top:12px;justify-content:flex-end"><button class="btn" data-act="pvDraft" data-id="${rv.id}" data-s="${s}">Save draft</button><button class="btn pri" data-act="pvSubmit" data-id="${rv.id}" data-s="${s}">${s==='m'?'Submit & notify HR':s==='h'?'Submit & notify employee':'Submit my section'}</button></div>`:''}</div>`; };
  const finalise = rv.stage===90 && st==='Awaiting decision' && isHR();
  return `<p class="no-print"><a href="#/probation">← Probation</a></p>
  <div class="ph"><div><h1 style="font-size:21px">${S.title}</h1><p>${esc(e.name)} · ${esc(e.title)} · ${esc(e.depts.join(' / '))}</p></div><div class="row wrap no-print">${statusBadge(st==='Complete'?'Complete':st)}<button class="btn" data-act="pvPrint">${ico('file')} Print / save as PDF</button></div></div>
  <div class="steps">${['Scheduled','Awaiting manager','Awaiting HR','Awaiting employee',rv.stage===90?'Awaiting decision':null,'Complete'].filter(Boolean).map((s,i,arr)=>{ const idx = arr.indexOf(st); return `<div class="step ${i<idx||st==='Complete'?'done':i===idx?'cur':''}"><i>${i+1}</i>${s.replace('Awaiting ','With ')}</div>`; }).join('')}</div>
  <div class="card" style="margin-bottom:14px"><div class="fgrid"><dl class="dl"><dt>Name</dt><dd>${esc(e.name)}</dd><dt>Job title</dt><dd>${esc(e.title)}</dd><dt>Location</dt><dd>${e.region==='PK'?'PK ☒  UK ☐':'PK ☐  UK ☒'}</dd><dt>Start date</dt><dd>${fmt(e.start)}</dd></dl><dl class="dl"><dt>Probation period</dt><dd>${rv.stage} days</dd><dt>Review date</dt><dd>${fmt(rv.due)}</dd><dt>Line manager</dt><dd>${esc(managersOf(e).map(empName).join(', '))}</dd>${rv.stage===90?`<dt>Current salary</dt><dd>${isMgr()||e.id===SESSION.uid?esc(e.salary?gbp(e.salary):'(see payroll)'):'—'}</dd>`:''}</dl></div>
  <div class="banner info" style="margin:12px 0 0">${ico('help')}<span><b>Attendance snapshot from the portal (start to review date):</b> holidays ${num1(snap.hol)} day(s) · sickness ${snap.sp} spell(s) / ${num1(snap.sickD)} day(s) · unauthorised absence ${num1(snap.un)} · late-approved-unpaid ${snap.late} · clocking anomalies ${snap.an}${snap.anTypes?' ('+esc(snap.anTypes)+')':''}</span></div></div>
  ${prior.filter(r=>r.status==='Complete'&&r.m&&Object.keys(r.m).length).length?`<div class="small muted" style="margin-bottom:10px">Earlier reviews completed: ${prior.filter(r=>r.status==='Complete').map(r=>`<a href="#/probation/${r.id}">${pvLabel(r)}</a>`).join(', ')}</div>`:''}
  ${['m','h','e'].map(part).join('')}
  ${rv.stage===90?`<div class="card" style="margin-bottom:14px"><h3>Sign-off</h3><div class="grid g3"><div><b class="small">Head of Department</b><div class="small">${rv.sigs.m?esc(rv.sigs.m.name)+' · '+fmtDT(rv.sigs.m.t):'<span class="muted">Pending</span>'}</div></div><div><b class="small">HR Department</b><div class="small">${rv.sigs.h?esc(rv.sigs.h.name)+' · '+fmtDT(rv.sigs.h.t):'<span class="muted">Pending</span>'}</div></div><div><b class="small">CEO</b><div class="small">${rv.sigs.ceo?esc(rv.sigs.ceo.name)+' · '+fmtDT(rv.sigs.ceo.t):'<span class="muted">Pending</span>'}${!rv.sigs.ceo&&(isCEO()||isAdmin())&&['Awaiting decision','Complete'].includes(st)?` <button class="btn sm no-print" data-act="pvCeo" data-id="${rv.id}">Sign as CEO</button>`:''}</div></div></div>
  <p class="small muted" style="margin:10px 0 0">Copy to: Employee personal file. ${rv.outcome?`<b>Outcome: ${esc(rv.outcome)}</b>`:''}</p></div>`:''}
  ${finalise?`<div class="card no-print" style="border-color:var(--navy2)"><h3>HR decision</h3><p class="muted small">Recommendations — Supervisor: <b>${esc(rv.m.rec||'—')}</b>, HR: <b>${esc(rv.h.rec||'—')}</b>. The decision is made by HR and approved by the CEO; the system records it and does not decide.</p><button class="btn pri" data-act="pvDecide" data-id="${rv.id}">Record decision…</button></div>`:''}
  ${rv.stage!==90&&st==='Complete'?`<p class="small muted">Review complete. ${rv.sigs.e?'Employee acknowledged '+fmtDT(rv.sigs.e.t)+'.':''}</p>`:''}
  <div class="card flat no-print" style="margin-top:14px"><h3>Audit trail</h3><div class="tl">${rv.log.slice().reverse().map(l=>`<div class="e"><b>${esc(l.w)}</b><div class="small muted">${fmtDT(l.t)}</div></div>`).join('')}</div></div>`;
}
const pvCollect = (rv, s) => { const f = $('#pv-'+s), out = {}; PSPEC[rv.stage][s].forEach(x => { out[x.k] = f.elements[x.k].value.trim(); }); return out; };
